from datetime import datetime, time

class Notifier:
    CHANNELS = ("email", "sms", "push")

    def __init__(self, quiet_start: time = time(22, 0), quiet_end: time = time(7, 0)) -> None:
        self.quiet_start = quiet_start
        self.quiet_end = quiet_end
        self.users = {}  # user -> {channel: enabled}

    def add_user(self, user: str) -> None:
        # Initialize user with email enabled, sms and push disabled
        self.users[user] = {
            "email": True,
            "sms": False,
            "push": False
        }

    def set_channel(self, user: str, channel: str, enabled: bool) -> None:
        if channel not in self.CHANNELS:
            raise ValueError(f"Channel must be one of {self.CHANNELS}")
        if user not in self.users:
            self.add_user(user)
        self.users[user][channel] = enabled

    def send(self, user: str, message: str, at: datetime) -> list[str]:
        if user not in self.users:
            return []

        # Determine if current time is during quiet hours
        # Convert datetime to time for comparison
        current_time = at.time()

        # Check if quiet hours apply (for sms and push only)
        is_quiet_hours = False
        if self.quiet_start <= self.quiet_end:
            # Normal case: quiet hours don't cross midnight
            is_quiet_hours = self.quiet_start <= current_time <= self.quiet_end
        else:
            # Quiet hours cross midnight (e.g., 22:00 to 07:00)
            is_quiet_hours = current_time >= self.quiet_start or current_time <= self.quiet_end

        delivered_channels = []

        # Check each channel in CHANNELS order
        for channel in self.CHANNELS:
            # Skip if channel is disabled for this user
            if not self.users[user].get(channel, False):
                continue

            # Skip sms and push during quiet hours
            if is_quiet_hours and channel in ("sms", "push"):
                continue

            # Email is always delivered if enabled
            delivered_channels.append(channel)

        return delivered_channels
